 public function preview(UploadedFile $file,int $academicYearId,User $actor):TeachingImportBatch
 {
  $stored=$file->store('teaching-assignment-imports','local');
  try{$sheets=$this->canonicalSheets($this->xlsx->read(Storage::disk('local')->path($stored)));$this->assertRequiredSheets($sheets);return DB::transaction(function()use($file,$stored,$sheets,$academicYearId,$actor){$batch=TeachingImportBatch::create(['academic_year_id'=>$academicYearId,'user_id'=>$actor->id,'original_filename'=>$file->getClientOriginalName(),'stored_filename'=>$stored,'status'=>'parsing','sheet_count'=>count($sheets),'sheet_names'=>array_keys($sheets)]);$people=Personnel::where('is_active',true)->get();$subjects=Subject::where('is_active',true)->get();$rooms=Classroom::with(['gradeLevel','homeroomPersonnel'])->where('academic_year_id',$academicYearId)->where('is_active',true)->get();$database=$this->parseDatabase($batch,$sheets[self::DATABASE],$people,$subjects,$rooms);$legger=$this->parseLegger($batch,$sheets[self::LEGGER],$people,$subjects,$rooms,$database['classrooms']);$template=$this->validateTemplate($sheets[self::REFERENCE]??null);$matchable=$batch->rows()->whereIn('row_type',['subject','personnel','classroom']);$statusCounts=collect(['matched','unmatched','selection','review'])->mapWithKeys(fn($status)=>[$status=>(clone $matchable)->where('status',$status)->count()]);$summary=['parser_version'=>'classroom-grade-name-v2','sheets'=>array_keys($sheets),'database'=>$database,'legger'=>$legger,'template'=>$template,'matching'=>['matched'=>$statusCounts['matched'],'unmatched'=>$statusCounts['unmatched'],'selection'=>$statusCounts['selection'],'review'=>$statusCounts['review']]];$batch->update(['status'=>'previewed','subject_count'=>$database['subject_count'],'structure_load_count'=>$database['structure_load_count'],'personnel_count'=>$database['personnel_count'],'classroom_count'=>$database['classroom_count'],'assignment_candidate_count'=>$legger['assignment_candidate_count'],'additional_duty_count'=>$legger['additional_duty_count'],'conflict_count'=>$legger['conflict_count'],'matched_rows'=>$statusCounts['matched'],'unmatched_rows'=>$statusCounts