 private function parseDatabase(TeachingImportBatch $batch,array $rows,Collection $people,Collection $subjects,Collection $rooms):array
 {
  $subjectCount=$personnelCount=$classroomCount=$loadCount=0;$subjectMatched=$personnelMatched=$classroomMatched=0;$totals=[];$sourceClassrooms=[];
  for($row=10;$row<=33;$row++)if($this->present($rows[$row][3]??null)){$name=trim((string)$rows[$row][3]);$match=$this->names->match($name,$people);$this->row($batch,self::DATABASE,$row,1,'personnel',['name'=>$name],['source_name'=>$name],$match['status'],['personnel'=>$match['match']]);$personnelCount++;if($match['status']==='matched')$personnelMatched++;}
  for($row=10;$row<=31;$row++){$name=trim((string)($rows[$row][6]??''));if(!$this->present($name))continue;$code=trim((string)($rows[$row][5]??''));$match=$this->names->match($name,$subjects,'name');$loads=[];foreach(range(8,14) as $column){$value=$rows[$row][$column]??null;$hours=$this->hours($value);$loads[]=$hours;if($hours!==null)$loadCount++;}$this->row($batch,self::DATABASE,$row,2,'subject',['code'=>$code,'name'=>$name,'category'=>$rows[$row][7]??null,'loads'=>$loads],['source_code'=>$code,'source_name'=>$name,'loads'=>$loads],$match['status'],['subject'=>$match['match']]);$subjectCount++;if($match['status']==='matched')$subjectMatched++;}
  for($row=10;$row<=21;$row++){$p=trim((string)($rows[$row][16]??''));$q=trim((string)($rows[$row][17]??''));$r=trim((string)($rows[$row][18]??''));$label=$this->classLabel($p,$q);if(!$this->present($label))continue;$match=$this->classrooms->match($label,$rooms);$homeroom=$this->names->match($r,$people);$comparison=$match['match']&&$homeroom['match']?($match['match']->homeroom_personnel_id===$homeroom['match']->id?'same':'different'):'unresolved';$status=$match['status']==='matched'&&$comparison==='different'?'review':$match['status'];$program=$this->classrooms->suggestProgram($label);$availability=$match['status']==='matched'?'matched':($match['status']==='selection'?'selection':'unavailable');$this->row($batch,self::DATABASE,$row,3,'classroom',['label'=>$label,'homeroom'=>$r],['source_name'=>$label,'parsed'=>$match['parsed'],'suggested_program'=>$program,'availability'=>$availability,'availability_message'=>$availability==='unavailable'?'Rombel dari file belum tersedia pada tahun ajaran yang dipilih.':null,'homeroom_source'=>$r,'homeroom_match_id'=>$homeroom['match']?->id,'homeroom_comparison'=>$comparison],$status,['classroom'=>$match['match'],'personnel'=>$homeroom['match']]);$classroomCount++;if($match['status']==='matched')$classroomMatched++;$sourceClassrooms[]=$label;}
  foreach(range(8,14) as $column)$totals[]=$this->hours($rows[34][$column]??null);
  return compact('subjectCount','loadCount','personnelCount','classroomCount','totals')+['subject_count'=>$subjectCount,'structure_load_count'=>$loadCount,'personnel_count'=>$personnelCount,'classroom_count'=>$classroomCount,'reference_totals'=>$totals,'classrooms'=>$sourceClassrooms,'matching'=>['subjects_matched'=>$subjectMatched,'subjects_unmatched'=>$subjectCount-$subjectMatched,'personnel_matched'=>$personnelMatched,'personnel_unmatched'=>$personnelCount-$personnelMatched,'classrooms_matched'=>$classroomMatched,'classrooms_unavailable'=>$classroomCount-$classroomMatched]];
 }
 private function parseLegger(TeachingImportBatch $batch,array $rows,Collection $people,Collection $subjects,Collection $rooms,array $sourceClassrooms):array
 {
  $headers=[];foreach(range(5,26) as $column)$headers[$column]=trim((string)($rows[4][$column]??''));$candidates=[];$duties=0;
  for($row=5;$row<=28;$row++){$teacher=trim((string)($rows[$row][2]??''));if(!$this->present($teacher))continue;$personMatch=$this->names->match($teacher,$people);$classText=trim((string)($rows[$row][4]??''));$sourceClassParts=$this->expandSourceClasses($classText,$sourceClassrooms);$duty=trim((string)($rows[$row][3]??''));if($this->present($duty)){$this->row($batch,self::LEGGER,$row,1,'additional_duty',['teacher'=>$teacher,'duty'=>$duty,'equivalent_periods'=>$this->hours($rows[$row][27]??null)??0],['source_name'=>$teacher,'duty_name'=>$duty,'equivalent_periods'=>$this->hours($rows[$row][27]??null)??0],$personMatch['status'],['personnel'=>$personMatch['match']]);$duties++;}$sequence=10;foreach($headers as $column=>$subjectName){if(!$this->present($subjectName)||!$this->selected($rows[$row][$column]??null))continue;$subjectMatch=$this->names->match($subjectName,$subjects,'name');foreach($sourceClassParts as $sourceClass){$roomMatch=$this->classrooms->match($sourceClass,$rooms);$status=$this->combinedStatus([$personMatch['status'],$subjectMatch['status'],$roomMatch['status']]);$personnelStatus=$personMatch['status']==='matched'?'matched':($personMatch['status']==='selection'?'selection':'unmatched');$subjectStatus=$subjectMatch['status']==='matched'?'matched':($subjectMatch['status']==='selection'?'selection':'new');$classroomStatus=$roomMatch['status']==='matched'?'matched':($roomMatch['status']==='selection'?'selection':'unavailable');$overallStatus=$personnelStatus==='matched'&&$subjectStatus==='matched'&&$classroomStatus==='matched'?'ready':($classroomStatus==='unavailable'?'waiting_classroom':'needs_review');$normalized=['teacher_source'=>$teacher,'subject_source'=>$subjectName,'classroom_source'=>$sourceClass,'component_statuses'=>['personnel'=>$personnelStatus,'subject'=>$subjectStatus,'classroom'=>$classroomStatus],'overall_status'=>$overallStatus,'blocking_reason'=>$classroomStatus==='unavailable'?'Rombel dari file belum tersedia pada tahun ajaran yang dipilih.':null,'personnel_ids'=>$personMatch['match']?[$personMatch['match']->id]:[],'subject_ids'=>$subjectMatch['match']?[$subjectMatch['match']->id]:[],'classroom_ids'=>$roomMatch['match']?[$roomMatch['match']->id]:[]];$this->row($batch,self::LEGGER,$row,$sequence++,'assignment_candidate',['teacher'=>$teacher,'subject'=>$subjectName,'classroom'=>$sourceClass,'selection'=>$rows[$row][$column]],$normalized,$status,['personnel'=>$personMatch['match'],'subject'=>$subjectMatch['match'],'classroom'=>$roomMatch['match']]);$candidates[]=$normalized;}}
  }
  $conflictGroups=collect($candidates)->filter(fn($item)=>$item['personnel_ids'])->groupBy(fn($item)=>$this->names->normalize($item['classroom_source']).'_'.$this->names->normalize($item['subject_source']))->filter(fn($group)=>$group->pluck('personnel_ids.0')->unique()->count()>1);$conflictDetails=$conflictGroups->map(fn($group)=>['classroom'=>$group->first()['classroom_source'],'subject'=>$group->first()['subject_source'],'teachers'=>$group->pluck('teacher_source')->unique()->values()->all()])->values()->all();
  return ['assignment_candidate_count'=>count($candidates),'additional_duty_count'=>$duties,'conflict_count'=>$conflictGroups->count(),'conflicts'=>$conflictDetails,'ignored_rows'=>'29-34'];
 }
 private function validateTemplate(?array $rows):array{if($rows===null)return ['available'=>false,'status'=>'Template cetak tidak ditemukan.'];$values=collect($rows)->flatten()->filter(fn($value)=>$this->present($value));return ['available'=>true,'status'=>'Template cetak ditemukan dan berhasil divalidasi.','sample_teacher'=>$values->first(fn($value)=>preg_match('/S\.?Pd|S\.?Ag/iu',(string)$value)),'calculated_value_available'=>$values->contains(fn($value)=>is_numeric($value))];}
 private function row(TeachingImportBatch $batch,string $sheet,int $number,int $sequence,string $type,array $raw,array $normalized,string $status,array $matches=[]):void{TeachingImportRow::create(['batch_id'=>$batch->id,'sheet_name'=>$sheet,'row_number'=>$number,'source_sequence'=>$sequence,'row_type'=>$type,'raw_data'=>$raw,'normalized_data'=>$normalized,'status'=>$status,'messages'=>[$this->statusMessage($status)],'matched_personnel_id'=>($matches['personnel']??null)?->id,'matched_subject_id'=>($matches['subject']??null)?->id,'matched_classroom_id'=>($matches['classroom']??null)?->id]);}
 private function combinedStatus(array $statuses):string{return in_array('selection',$statuses,true)?'selection':(in_array('unmatched',$statuses,true)?'unmatched':(in_array('review',$statuses,true)?'review':'matched'));}
 private function statusMessage(string $status):string{return match($status){'matched'=>'Data sudah cocok.','selection'=>'Ditemukan beberapa pilihan. Pilih data yang benar.','review'=>'Data perlu diperiksa.','conflict'=>'Konflik pengampu perlu diselesaikan.',default=>'Data belum cocok dengan aplikasi.'};}
 private function present(mixed $value):bool{return !in_array(trim((string)$value),self::EMPTY,true);}
 private function hours(mixed $value):?int{$hours=$this->present($value)&&is_numeric($value)?(int)round((float)$value):null;return $hours!==null&&$hours>0?$hours:null;}
 private function selected(mixed $value):bool{return $this->present($value)&&(!is_numeric($value)||(float)$value>0);}
